      "title": "Measurement Id",
      "type": "string"
     }
    },
    "required": [
     "measurement_id"
    ],
    "type": "object",
    "title": "peaksArguments"
   },
   "returns": "a JSON object; see the description (call returns it as a dict)"
  },
